const cfg = $('Set config: your profile & search').first().json;
const kw = encodeURIComponent((cfg.position || '').split(',')[0].trim() || 'product manager');
const sources = [
  { source: 'RemoteOK',  url: 'https://remoteok.com/api' },
  { source: 'Remotive',  url: 'https://remotive.com/api/remote-jobs?search=' + kw },
  { source: 'Arbeitnow', url: 'https://www.arbeitnow.com/api/job-board-api' },
  { source: 'Jobicy',    url: 'https://jobicy.com/api/v2/remote-jobs?count=50' },
  { source: 'Himalayas', url: 'https://himalayas.app/jobs/api?limit=50' },
  { source: 'TheMuse',   url: 'https://www.themuse.com/api/public/jobs?page=1' },
];
if (cfg.adzunaAppId && cfg.adzunaAppKey) {
  const countries = String(cfg.adzunaCountry || 'us').toLowerCase().split(',').map((s) => s.trim()).filter(Boolean);
  for (const c of countries) sources.push({ source: 'Adzuna', url: 'https://api.adzuna.com/v1/api/jobs/' + c + '/search/1?app_id=' + cfg.adzunaAppId + '&app_key=' + cfg.adzunaAppKey + '&results_per_page=50&what=' + kw });
}
return sources.map((s) => ({ json: s }));

const cfg = $('Set config: your profile & search').first().json;
const srcIn = $('Expand job sources').all();
const strip = (h) => String(h || '').replace(/<[^>]+>/g, ' ').replace(/&[a-z#0-9]+;/g, ' ').replace(/\s+/g, ' ').trim();
const srcOf = (it, idx) => { let pi = it.pairedItem; let p = (typeof pi === 'number') ? pi : (Array.isArray(pi) ? (pi[0] || {}).item : (pi || {}).item); if (p == null) p = idx; return (srcIn[p] && srcIn[p].json.source) || ''; };

// per-source adapters -> { title, company, city, remote, url, desc, salaryMax }
function adapt(source, j) {
  const A = [];
  const push = (o) => { if (o.title && o.url) A.push({ salaryMax: 0, ...o, source }); };
  if (source === 'RemoteOK' && Array.isArray(j)) for (const r of j) { if (r.legal || !r.position) continue; push({ title: r.position, company: r.company || '', city: r.location || 'Remote', remote: true, url: r.url, desc: strip(r.description), salaryMax: Number(r.salary_max) || 0 }); }
  else if (source === 'Remotive') for (const r of (j.jobs || [])) push({ title: r.title, company: r.company_name || '', city: r.candidate_required_location || 'Remote', remote: true, url: r.url, desc: strip(r.description) });
  else if (source === 'Arbeitnow') for (const r of (j.data || [])) push({ title: r.title, company: r.company_name || '', city: r.location || 'Remote', remote: !!r.remote, url: r.url, desc: strip(r.description) });
  else if (source === 'Jobicy') for (const r of (j.jobs || [])) push({ title: r.jobTitle, company: r.companyName || '', city: r.jobGeo || 'Remote', remote: true, url: r.url, desc: strip(r.jobExcerpt), salaryMax: Number(r.annualSalaryMax) || 0 });
  else if (source === 'Himalayas') for (const r of (j.jobs || [])) push({ title: r.title, company: r.companyName || '', city: (r.locationRestrictions || []).join(', ') || 'Remote', remote: true, url: r.applicationLink || r.guid, desc: strip(r.excerpt || r.description), salaryMax: (String(r.salaryPeriod || '').toLowerCase().startsWith('year') ? Number(r.maxSalary) || 0 : 0) });
  else if (source === 'TheMuse') for (const r of (j.results || [])) push({ title: r.name, company: (r.company || {}).name || '', city: (r.locations || []).map((l) => l.name).join(', ') || 'Flexible', remote: /remote|flexible/i.test(((r.locations || []).map((l) => l.name).join(' '))), url: (r.refs || {}).landing_page, desc: strip(r.contents) });
  else if (source === 'Adzuna') for (const r of (j.results || [])) push({ title: r.title, company: (r.company || {}).display_name || '', city: (r.location || {}).display_name || '', remote: /remote/i.test(r.title + ' ' + ((r.location || {}).display_name || '')), url: r.redirect_url, desc: strip(r.description), salaryMax: Number(r.salary_max) || 0 });
  return A;
}

const lc = (s) => String(s || '').toLowerCase();
const list = (s) => lc(s).split(',').map((x) => x.trim()).filter(Boolean);
const positions = list(cfg.position);   // title must contain one of these
const tags = list(cfg.tags);            // title/desc must contain one of these (if set)
const excludes = list(cfg.excludeTerms);// title must NOT contain any of these
const locs = list(cfg.locations);
const remoteOnly = /^(y|yes|true|1)$/i.test(cfg.remoteOnly || '');
const minSalary = Number(cfg.minSalary) || 0;
const posOk = (t) => positions.length === 0 || positions.some((p) => lc(t).includes(p));
const tagOk = (t, d) => tags.length === 0 || tags.some((g) => (lc(t) + ' ' + lc(d)).includes(g));
const exclOk = (t) => !excludes.some((e) => lc(t).includes(e));
const locationOk = (job) => job.remote || locs.some((l) => l === 'worldwide' || lc(job.city).includes(l)) || !job.city;

const seen = new Set(); const jobs = [];
const responses = $input.all();
for (let idx = 0; idx < responses.length; idx++) {
  const raw = responses[idx].json;
  let j; if (typeof raw === 'string') { try { j = JSON.parse(raw); } catch (e) { continue; } }
  else if (raw && typeof raw.data === 'string') { try { j = JSON.parse(raw.data); } catch (e) { continue; } }
  else j = raw;
  const source = srcOf(responses[idx], idx);
  for (const job of adapt(source, j)) {
    // apply the config filters
    if (!posOk(job.title)) continue;                                   // position/title
    if (!exclOk(job.title)) continue;                                  // exclude terms
    if (!tagOk(job.title, job.desc)) continue;                         // tags/skills
    if (remoteOnly && !job.remote) continue;                           // remote yes/no
    if (minSalary > 0 && job.salaryMax > 0 && job.salaryMax < minSalary) continue; // salary (kept if unknown)
    const key = (job.company + '|' + job.title).toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    jobs.push({ ...job, desc: job.desc.slice(0, 700), locationOk: locationOk(job) });
  }
}
// prefer location-matching jobs, then cap
jobs.sort((a, b) => (b.locationOk === a.locationOk) ? 0 : (b.locationOk ? 1 : -1));
const capped = jobs.slice(0, Number(cfg.maxJobs) || 12).map((j, i) => ({ i, ...j }));
return [{ json: { jobs: capped, count: capped.length, sources: [...new Set(capped.map((j) => j.source))] } }];

const cfg = $('Set config: your profile & search').first().json;
const jobs = $('Normalize & merge job boards').first().json.jobs || [];
const min = Number(cfg.minScore) || 0;
// AI Agent (with structured output parser) returns the parsed object under 'output';
// fall back to a raw JSON string or an Anthropic content block if the shape differs.
let scores = [];
const j = $json;
const cand = (j.output && j.output.scores) ? j.output.scores : (j.scores ? j.scores : null);
if (cand) scores = cand;
else {
  let text = '';
  if (typeof j.output === 'string') text = j.output;
  else if (Array.isArray(j.content)) text = ((j.content.find((b) => b.type === 'text') || {}).text) || '';
  else if (typeof j.text === 'string') text = j.text;
  try { scores = (JSON.parse(text).scores) || []; } catch (e) { scores = []; }
}
const esc = (s) => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const merged = scores.map((s) => ({ ...s, ...(jobs[s.i] || {}) })).filter((m) => m.url && m.score >= min).sort((a, b) => b.score - a.score);
const rows = merged.map((m) =>
  '<tr><td style="padding:6px 10px;font-weight:700;vertical-align:top">' + m.score + '</td>' +
  '<td style="padding:6px 10px"><a href="' + esc(m.url) + '">' + esc(m.title) + '</a><br>' +
  '<span style="color:#555">' + esc(m.company) + ' · ' + (m.remote ? 'Remote' : 'Onsite') + (m.city && m.city !== 'Remote' ? ' · ' + esc(m.city) : '') + (m.salaryMax ? ' · ~' + Math.round(m.salaryMax / 1000) + 'k' : '') + ' · via ' + esc(m.source) + '</span><br>' +
  '<span style="color:#111">' + esc(m.fit) + '</span>' +
  (m.concerns && m.concerns.toLowerCase() !== 'none' ? '<br><span style="color:#a00">⚠ ' + esc(m.concerns) + '</span>' : '') +
  '<br><span style="color:#036"><em>Pitch: ' + esc(m.pitch) + '</em></span></td></tr>').join('');
const html = merged.length
  ? '<h2>Your job matches</h2><p style="color:#555">' + merged.length + ' roles at or above score ' + min + ', from ' + (jobs.length ? [...new Set(jobs.map((j) => j.source))].length : 0) + ' boards, ranked by fit.</p>' +
    '<table style="border-collapse:collapse;font-family:system-ui,Arial"><tr><th style="text-align:left;padding:6px 10px">Fit</th><th style="text-align:left;padding:6px 10px">Role</th></tr>' + rows + '</table>'
  : '<p>No roles scored at or above ' + min + ' today. Widen your keywords or lower the threshold in the config node.</p>';
const subject = merged.length ? 'Job matches: ' + merged.length + ' roles (top ' + merged[0].score + '/100)' : 'Job matches: nothing above your threshold today';
return [{ json: { subject, html, count: merged.length } }];
